import { loadRows, loadStats, loadDynamic } from '../network';
/** 采购台账：供应商筛选。 */
export function Board() {
  async function search() { return loadRows(); }
  async function statistics() { return loadStats(); }
  return <main><button onClick={search}>查询</button><button onClick={statistics}>汇总</button><button onClick={loadDynamic}>动态查询</button></main>;
}
export default Board;

import { search } from './jobs';
export const moduleInfo = { key: 'purchase', name: '采购模块' };
scheduler.register('nightly-ledger', search);
messages.subscribe('purchase.refresh', search);
commands.register('refresh-ledger', search);

import { http } from './client';
export function loadRows() { return http.get('/purchase/ledger'); }
export function loadStats() { return http.graphql(`query PurchaseSummary { purchaseSummary { count } }`); }
export function loadDynamic() { return http.get('/purchase/' + globalThis.target); }
